                        <button id="behavior-connect-cancel-btn" style="padding:4px 8px; border:1px solid #b9cddd; background:#fff; color:#2f4858; border-radius:5px; cursor:pointer; font-size:0.82em;">\u63A5\u7D9A\u89E3\u9664</button>
